// Space Grotesk and Inter (Google Fonts, OFL licensed), both embedded as
// data URIs so the site renders its type without depending on an external
// font host at request time. Both are variable fonts, one file per family
// spans the full weight range used across the site (500/600/700 for
// Space Grotesk display type, 400/500/600 for Inter body/UI text).
export const SPACE_GROTESK_WOFF2_BASE64 = "";

export const INTER_WOFF2_BASE64 = "";

// satori (via @vercel/og) can't parse woff2 in the version this project
// pins (it throws "Unsupported OpenType signature wOF2"), so the badge
// route needs its own woff1 copies of the same two families, used only
// there. Everything CSS-rendered (theme.ts, report-page.ts) keeps woff2
// above; this trio exists solely for renderBadge()'s ImageResponse call.
export const SPACE_GROTESK_WOFF_BADGE_BASE64 = "";
export const INTER_400_WOFF_BADGE_BASE64 = "";
export const INTER_600_WOFF_BADGE_BASE64 = "";
